package com.example.leavemanagement.calendar.api;
import com.example.leavemanagement.calendar.application.ManagerTeamCalendarService;import com.example.leavemanagement.shared.security.CurrentActorProvider;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/manager/team-calendar") public class ManagerCalendarController {private final ManagerTeamCalendarService calendars;private final CurrentActorProvider actors;public ManagerCalendarController(ManagerTeamCalendarService calendars,CurrentActorProvider actors){this.calendars=calendars;this.actors=actors;}@GetMapping public List<ManagerTeamCalendarService.Entry> calendar(@RequestParam LocalDate from,@RequestParam LocalDate to){return calendars.entries(actors.require().employeeId(),from,to);}}
